/// <summary>
/// Processes customer ASNs by validating CCR data, triggering the despatch advice event, and marking CCR records as received.
/// Task 355193: PB168 - E2E - SO ASN to Ampol - D365
/// </summary>
public class METCustomerASNProcessor
{
}

Method.Source:
/// <summary>
/// Constructs a new instance of the METCustomerASNProcessor class.
/// </summary>
public static METCustomerASNProcessor construct()
{
    return new METCustomerASNProcessor();
}

/// <summary>
/// Validates CCR data for the sales order and, when everything matches,
/// triggers the business event and marks CCR Received = Yes.
/// </summary>
/// <param name = "_salesTable">Sales order to process.</param>
/// <returns>true if the event was triggered; false if data is not ready.</returns>
public boolean processSalesOrder(SalesTable _salesTable)
{
    boolean                 isRouteId = false;
    SalesTable              salesTable = _salesTable;
    WMSPickingRoute         pickingRoute = this.findSalesPickingRoute(_salesTable.SalesId);
    InventLocation          inventLocation;
    WMSPickingRouteID       ccrPickingRouteId;
    METWMSPicklistNumber    wmsPicklistNumber;

    if (!salesTable.RecId || !pickingRoute.RecId)
    {
        return false;
    }

    inventLocation = InventLocation::find(pickingRoute.inventLocationId);

    if (inventLocation.METCCR == NoYes::Yes && inventLocation.METPickDirector == NoYes::No)
    {
        wmsPicklistNumber = this.getSourceTOWMSPicklistNumber(pickingRoute.METTransferOrderPickingRouteId);
        ccrPickingRouteId = wmsPicklistNumber;

        isRouteId = true;
    }
    else if (inventLocation.METCCR == NoYes::No && inventLocation.METPickDirector == NoYes::Yes)
    {
        ccrPickingRouteId = salesTable.SalesId;
    }

    if (!ccrPickingRouteId || !this.validateCCRData(salesTable, ccrPickingRouteId, isRouteId))
    {
        return false;
    }

    this.triggerBusinessEvent(salesTable, wmsPicklistNumber);
    this.markCCRReceived(salesTable.SalesId);

    return true;
}

/// <summary>
/// Finds the picking route attached to the sales order.
/// </summary>
/// <param name = "_salesId">Sales order.</param>
/// <returns>The sales order's picking route record.</returns>
private WMSPickingRoute findSalesPickingRoute(SalesId _salesId)
{
    WMSPickingRoute pickingRoute;

    select firstonly pickingRoute
        where pickingRoute.transType  == InventTransType::Sales
           && pickingRoute.transRefId == _salesId;

    return pickingRoute;
}

/// <summary>
/// Gets the WMS picklist number for the Source TO picking route.
/// </summary>
/// <param name = "_sourceWMSPickingRouteNumber">Source TO picking route id.</param>
/// <returns>WMS picklist number, or blank when there is no Source TO route.</returns>
private METWMSPicklistNumber getSourceTOWMSPicklistNumber(METWMSPicklistNumber _sourceWMSPickingRouteNumber)
{
    WMSPickingRoute         sourceWMSPickingRoute;
    METPicklistReference    picklistReference;

    if (!_sourceWMSPickingRouteNumber)
    {
        return '';
    }

    select firstonly RecId from sourceWMSPickingRoute
        where sourceWMSPickingRoute.transType      == InventTransType::TransferOrderShip
           && sourceWMSPickingRoute.pickingRouteID == _sourceWMSPickingRouteNumber
        join WMSPicklistNumber from picklistReference
        where picklistReference.D365FOPicklistNumber == sourceWMSPickingRoute.pickingRouteID;

    return picklistReference.WMSPicklistNumber;
}

/// <summary>
/// Validates METCCRTable against WMSOrderTrans picked cases.
/// </summary>
/// <param name = "_salesTable">Sales order being processed.</param>
/// <param name = "_ccrPickingRouteId">Key used to look up the CCR records.</param>
/// <returns>true when every item matches in both tables; otherwise false.</returns>
private boolean validateCCRData(SalesTable _salesTable, WMSPickingRouteID _ccrPickingRouteId, boolean _isRouteId = false)
{
    METCCRTable     ccrAgg;
    WMSOrderTrans   wmsOrderTrans;
    Map             ccrQtyByItem = new Map(Types::String, Types::Real);
    Map             wmsQtyByItem = new Map(Types::String, Types::Real);

    while select ItemId, sum(UOIPickedQty) from ccrAgg
        group by ccrAgg.ItemId
        where ccrAgg.PickingRouteId == _ccrPickingRouteId
           && ccrAgg.CCRReceived    == NoYes::No
    {
        ccrQtyByItem.insert(ccrAgg.ItemId, ccrAgg.UOIPickedQty);
    }

    if (!ccrQtyByItem.elements())
    {
        return false;
    }

    while select ItemId, sum(METPickedCases) from wmsOrderTrans
        group by wmsOrderTrans.ItemId
        where wmsOrderTrans.expeditionStatus == WMSExpeditionStatus::Complete   &&
            wmsOrderTrans.inventTransType == inventTransType::Sales             &&
            ((_isRouteId && wmsOrderTrans.routeId == _ccrPickingRouteId)        ||
             (!_isRouteId && wmsOrderTrans.inventTransRefId == _salesTable.SalesId))
    {
        wmsQtyByItem.insert(wmsOrderTrans.ItemId, wmsOrderTrans.METPickedCases);
    }

    if (ccrQtyByItem.elements() != wmsQtyByItem.elements())
    {
        return false;
    }

    MapEnumerator mapEnum = wmsQtyByItem.getEnumerator();

    while (mapEnum.moveNext())
    {
        ItemId itemId = mapEnum.currentKey();

        if (!ccrQtyByItem.exists(itemId)
            || ccrQtyByItem.lookup(itemId) != mapEnum.currentValue())
        {
            return false;
        }
    }

    return true;
}

/// <summary>
/// Marks all unreceived CCR records for the key as CCR Received = Yes.
/// </summary>
/// <param name = "_ccrPickingRouteId">Key identifying the CCR records.</param>
private void markCCRReceived(SalesId _salesId)
{
    METCCRTable ccrTable;

    ttsbegin;
    update_recordset ccrTable
        setting CCRReceived = NoYes::Yes
        where ccrTable.SalesId == _salesId
           && ccrTable.CCRReceived == NoYes::No;
    ttscommit;
}

/// <summary>
/// Builds the event payload and sends the despatch advice business event.
/// </summary>
/// <param name = "_salesTable">Sales order being processed.</param>
/// <param name = "_wmsPicklistNumber">WMS picklist number for the payload.</param>
private void triggerBusinessEvent(SalesTable _salesTable, METWMSPicklistNumber _wmsPicklistNumber)
{
    METCustTable custTable = METCustTable::find(_salesTable.CustAccount);

    METDespatchAdviceEvent event = METDespatchAdviceEvent::newFromSalesOrder(
        _salesTable.dataAreaId,
        _salesTable.SalesId,
        custTable.METEDISenderCode,
        _wmsPicklistNumber);

    event.send();
}
